import { startLogin } from "@/const";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { useLanguage } from "@/contexts/LanguageContext";
import { CATEGORY_LABELS, formatMoney, ORDER_STATUS_LABELS, REQUEST_STATUS_LABELS } from "@shared/catalog";
import type { Product } from "../../../drizzle/schema";
import { motion } from "framer-motion";
import {
  ArrowLeft, ArrowRight, ArrowUpRight, Bold, Check, ChevronDown, CircleUserRound, Clipboard, ClipboardList, Clock3, Cpu, Copy, Download, ExternalLink, Gamepad2, GripVertical, Heart, ImagePlus, Italic, LayoutDashboard, Link as LinkIcon, List, ListOrdered, Loader2, LogIn, Menu, Package, PanelLeftClose, Plus, Search, Send, Settings, ShieldCheck, ShoppingBag, Sparkles, Star, Trash2, Truck, Users, X, Zap,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { Link, useLocation, useRoute } from "wouter";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";

const HERO_ART = "/manus-storage/gaming-pub-neon_fdf3de65.jpg";

type CategoryKey = keyof typeof CATEGORY_LABELS;

function cn(...values: Array<string | false | undefined>) { return values.filter(Boolean).join(" "); }

function formatDate(value: Date | string | null | undefined) {
  if (!value) return "—";
  return new Date(value).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
}

function LoginPanel({ title = "Sign in to continue", body = "Your account keeps orders, favorites, and requests private." }: { title?: string; body?: string }) {
  return <div className="glass-panel p-8 text-center max-w-lg mx-auto"><div className="eyebrow mb-3">ACCOUNT ACCESS</div><h2 className="font-display text-2xl text-white mb-3">{title}</h2><p className="text-slate-400 mb-6">{body}</p><Button onClick={() => startLogin()} className="neon-button"><LogIn className="w-4 h-4 mr-2" /> Sign in securely</Button></div>;
}

function StoreShell({ children }: { children: React.ReactNode }) {
  const { user, isAuthenticated, logout } = useAuth(); const { t, toggleLanguage } = useLanguage();
  const [open, setOpen] = useState(false);
  const cart = trpc.customer.cart.useQuery(undefined, { enabled: isAuthenticated, retry: false });
  const [location] = useLocation();
  const nav = [["games", "/games"], ["movies", "/movies"], ["series", "/series"], ["hardware", "/hardware"], ["request", "/request"]] as const;
  return <div className="min-h-screen bg-ink text-slate-200">
    <div className="scanline" />
    <header className="site-header">
      <div className="max-w-[1440px] mx-auto px-5 lg:px-10 h-[76px] flex items-center justify-between gap-6">
        <Link href="/" className="flex items-center gap-3 shrink-0"><div className="brand-mark"><span>GP</span></div><div><div className="font-display font-bold tracking-[.18em] text-white text-sm">GAMING PUB</div><div className="text-[9px] tracking-[.26em] text-cyan-300/70">CURATED DIGITAL GOODS</div></div></Link>
        <nav className="hidden lg:flex items-center gap-5 text-[11px] tracking-[.16em] font-semibold text-slate-400">{nav.map(([key, href]) => <Link key={href} href={href} className={cn("nav-link", location === href && "active")}>{t(key)}</Link>)}</nav>
        <div className="flex items-center gap-2">
          <button type="button" className="language-toggle hidden sm:flex" onClick={toggleLanguage} aria-label={t("language")}>{t("language")}</button><Link href="/search" aria-label={t("search")} className="icon-button"><Search className="w-4 h-4" /></Link>
          <Link href="/cart" aria-label="Cart" className="icon-button relative"><ShoppingBag className="w-4 h-4" />{(cart.data?.items.length ?? 0) > 0 && <span className="cart-dot">{cart.data?.items.length}</span>}</Link>
          {isAuthenticated ? <Link href={user?.role === "admin" ? "/admin/account" : "/account"} aria-label="Account" className="hidden sm:flex icon-button"><CircleUserRound className="w-4 h-4" /></Link> : <button type="button" onClick={() => startLogin()} aria-label="Sign in" className="hidden sm:grid icon-button"><CircleUserRound className="w-4 h-4" /></button>}
          <button className="lg:hidden icon-button" onClick={() => setOpen(!open)} aria-label="Toggle menu">{open ? <X className="w-4 h-4" /> : <Menu className="w-4 h-4" />}</button>
        </div>
      </div>
      {open && <div className="lg:hidden border-t border-white/10 bg-[#090d14] px-5 py-4 space-y-2">{nav.map(([key, href]) => <Link key={href} onClick={() => setOpen(false)} href={href} className="block py-2 text-xs tracking-[.16em] text-slate-300">{t(key)}</Link>)}<button type="button" onClick={toggleLanguage} className="block py-2 text-xs tracking-[.16em] text-cyan-300">{t("language")}</button>{isAuthenticated ? <Link onClick={() => setOpen(false)} href={user?.role === "admin" ? "/admin/account" : "/account"} className="block py-2 text-xs tracking-[.16em] text-cyan-300">{user?.role === "admin" ? t("adminAccount") : t("account")}</Link> : <button type="button" onClick={() => { setOpen(false); startLogin(); }} className="block py-2 text-xs tracking-[.16em] text-cyan-300">{t("account")}</button>}</div>}
    </header>
    <motion.main key={location} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: .28, ease: "easeOut" }}>{children}</motion.main>
    <footer className="border-t border-white/10 mt-20"><div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-12 grid md:grid-cols-[1.5fr_1fr_1fr_1fr] gap-10"><div><div className="flex items-center gap-3 mb-5"><div className="brand-mark small"><span>GP</span></div><span className="font-display font-bold tracking-[.16em] text-white">GAMING PUB</span></div><p className="text-sm text-slate-500 max-w-sm leading-7">A cinematic storefront for legitimate games, movies, series, and hardware. Orders are reviewed with care and communicated directly.</p></div><FooterColumn title="Explore" links={[["Games", "/games"], ["Movies", "/movies"], ["Series", "/series"], ["Hardware", "/hardware"]]} /><FooterColumn title="Account" links={[["Your account", "/account"], ["Orders", "/account/orders"], ["Favorites", "/account/favorites"], ["Request Center", "/request"]]} /><div><div className="eyebrow mb-4">STORE SIGNAL</div><div className="flex items-center gap-2 text-sm text-slate-400"><span className="signal-dot" /> Communications open</div><p className="text-xs text-slate-600 mt-4">WhatsApp links are for order discussion only. They never confirm payment.</p></div></div><div className="max-w-[1440px] mx-auto px-5 lg:px-10 pb-8 text-xs text-slate-600 flex flex-wrap gap-4 justify-between"><span>© {new Date().getFullYear()} Gaming Pub</span><span>Built for the next session.</span></div></footer>
    {isAuthenticated && user?.role === "admin" && <Link href="/admin" className="admin-float"><LayoutDashboard className="w-4 h-4" /> ADMIN</Link>}
    {isAuthenticated && <button className="sr-only" onClick={logout}>Sign out</button>}
  </div>;
}

function FooterColumn({ title, links }: { title: string; links: Array<[string, string]> }) { return <div><div className="eyebrow mb-4">{title}</div><div className="space-y-3">{links.map(([label, href]) => <Link key={href} href={href} className="block text-sm text-slate-500 hover:text-cyan-300 transition-colors">{label}</Link>)}</div></div>; }

function SectionHeading({ eyebrow, title, action }: { eyebrow: string; title: string; action?: React.ReactNode }) { return <div className="flex items-end justify-between gap-4 mb-7"><div><div className="eyebrow mb-2">{eyebrow}</div><h2 className="font-display text-2xl md:text-3xl tracking-tight text-white">{title}</h2></div>{action}</div>; }

function ProductCard({ product, favoriteIds = [], onNeedAuth }: { product: Product; favoriteIds?: number[]; onNeedAuth: () => void }) {
  const { isAuthenticated } = useAuth();
  const [, navigate] = useLocation();
  const favorite = favoriteIds.includes(product.id);
  const favMutation = trpc.customer.toggleFavorite.useMutation({ onSuccess: () => toast.success(favorite ? "Removed from favorites" : "Saved to favorites") });
  const cartMutation = trpc.customer.addToCart.useMutation({ onSuccess: () => { if (product.category === "HARDWARE") navigate("/checkout"); else toast.success("Added to cart"); }, onError: (error) => toast.error(error.message) });
  const available = product.availability && product.price !== null;
  return <motion.article whileHover={{ y: -4 }} transition={{ duration: .18 }} className="product-card group">
    <Link href={`/products/${product.slug}`} className="block">
      <div className="product-art"><img src={product.coverImage ?? HERO_ART} alt={`${product.name} abstract cover`} /><div className="art-overlay" /><div className="product-type">{CATEGORY_LABELS[product.category]}</div>{product.featured && <div className="product-featured">FEATURED</div>}<div className="product-scan" /></div>
      <div className="pt-4 px-4"><div className="flex items-start justify-between gap-3"><h3 className="font-display font-semibold text-white leading-tight group-hover:text-cyan-200 transition-colors">{product.name}</h3><span className={cn("status-dot mt-1", available ? "on" : "off")} /></div><div className="mt-3 flex items-center justify-between"><span className="text-sm font-semibold text-cyan-300">{formatMoney(product.price)}</span><span className="text-[10px] uppercase tracking-wider text-slate-600">{available ? "Available" : "Awaiting price"}</span></div></div>
    </Link>
    <div className="flex gap-2 p-4 pt-3"><Button aria-label={favorite ? "Remove favorite" : "Add favorite"} variant="ghost" size="icon" className={cn("h-9 w-9 border border-white/10", favorite && "text-pink-300 border-pink-300/30")} onClick={() => { if (!isAuthenticated) return onNeedAuth(); favMutation.mutate({ productId: product.id }); }}><Heart className={cn("w-4 h-4", favorite && "fill-current")} /></Button><Button className="h-9 flex-1 bg-white/5 hover:bg-cyan-300 hover:text-slate-950 border border-white/10" disabled={!available || cartMutation.isPending} onClick={() => { if (!isAuthenticated) return onNeedAuth(); cartMutation.mutate({ productId: product.id, quantity: 1 }); }}>{available ? (product.category === "HARDWARE" ? "Buy hardware" : "Add to cart") : "Unavailable"}</Button></div>
  </motion.article>;
}

function ProductGrid({ products, favoriteIds, onNeedAuth }: { products: Product[]; favoriteIds?: number[]; onNeedAuth: () => void }) { return <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5">{products.map((product, index) => <motion.div key={product.id} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: Math.min(index * .04, .28) }}><ProductCard product={product} favoriteIds={favoriteIds} onNeedAuth={onNeedAuth} /></motion.div>)}</div>; }

export function HomePage() {
  const { isAuthenticated } = useAuth();
  const featured = trpc.catalog.list.useQuery({ limit: 8, sort: "newest" });
  const available = trpc.catalog.list.useQuery({ limit: 8, availableOnly: true, sort: "newest" });
  return <StoreShell><section className="hero-shell"><div className="hero-art" style={{ backgroundImage: `url(${HERO_ART})` }} /><div className="hero-grid" /><div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-24 md:py-32 relative"><div className="max-w-3xl"><div className="eyebrow mb-6 flex items-center gap-3"><span className="signal-dot" /> CURATED FOR THE NEXT SESSION</div><h1 className="font-display text-5xl sm:text-7xl lg:text-[92px] leading-[.94] tracking-[-.05em] font-bold text-white">THE STORE<br /><span className="text-gradient">AFTER DARK.</span></h1><p className="mt-8 text-slate-300 max-w-xl text-base md:text-lg leading-8">A considered catalog of games, cinema, series, and hardware — with transparent availability and order conversations that stay human.</p><div className="flex flex-wrap gap-3 mt-9"><Link href="/games"><Button className="neon-button h-12 px-6">Explore the catalog <ArrowRight className="w-4 h-4 ml-2" /></Button></Link><Link href="/request"><Button variant="outline" className="h-12 px-6 border-white/20 text-slate-200 bg-black/20">Request a title</Button></Link></div></div><div className="hero-meta"><div><span className="text-cyan-300">01</span><span>Legitimate listings</span></div><div><span className="text-cyan-300">02</span><span>Human order review</span></div><div><span className="text-cyan-300">03</span><span>Private customer data</span></div></div></div></section><section className="max-w-[1440px] mx-auto px-5 lg:px-10 py-20"><SectionHeading eyebrow="LIVE INVENTORY" title="Ready when you are" action={<Link href="/search" className="inline-flex items-center gap-2 text-sm text-cyan-300 hover:text-white">View search <ArrowRight className="w-4 h-4" /></Link>} />{available.isLoading ? <GridSkeleton /> : available.data?.length ? <ProductGrid products={available.data} favoriteIds={isAuthenticated ? undefined : undefined} onNeedAuth={() => startLogin()} /> : <EmptyState title="The shelves are being calibrated" body="Prices and inventory are admin-configured. No products are currently available for purchase — browse the catalog or request something specific." action={<Link href="/request"><Button variant="outline" className="border-white/15">Open Request Center</Button></Link>} />}</section><section className="max-w-[1440px] mx-auto px-5 lg:px-10 pb-20"><div className="feature-band"><div className="max-w-xl"><div className="eyebrow mb-3">ONE CATALOG / FOUR WORLDS</div><h2 className="font-display text-3xl md:text-5xl text-white tracking-tight">Find your next<br /><span className="text-cyan-300">obsession.</span></h2><p className="text-slate-400 mt-5 leading-7">No clutter, no invented ratings, no mystery stock. Just a clean signal on what is available now and what is still being configured.</p></div><div className="category-orbit">{([["GAMES", "/games", Gamepad2], ["MOVIES", "/movies", Star], ["SERIES", "/series", ClipboardList], ["HARDWARE", "/hardware", Cpu]] as Array<[string, string, React.ElementType]>).map(([label, href, Icon]) => <Link key={String(href)} href={String(href)} className="orbit-card"><Icon className="w-5 h-5 text-cyan-300" /><span>{label}</span><ArrowUpRight /></Link>)}</div></div></section><section className="max-w-[1440px] mx-auto px-5 lg:px-10 pb-20"><SectionHeading eyebrow="CATALOG SIGNAL" title="Every title has a place" /><div className="grid md:grid-cols-3 gap-5"><InfoTile icon={<Zap />} title="Transparent by design" body="Unavailable means unavailable. We never invent prices, ratings, or stock to make a card look complete." /><InfoTile icon={<Truck />} title="Review before handoff" body="Every order moves through a visible status timeline. WhatsApp is for discussion, never payment confirmation." /><InfoTile icon={<Sparkles />} title="Request the missing" body="If it is not on the shelf, send a request with the details our team needs to find the right edition." /></div></section><section className="max-w-[1440px] mx-auto px-5 lg:px-10 pb-28"><SectionHeading eyebrow="FULL CATALOG" title="Explore the signal" action={<Link href="/search" className="text-sm text-cyan-300">Search all products</Link>} />{featured.isLoading ? <GridSkeleton /> : <ProductGrid products={featured.data ?? []} onNeedAuth={() => startLogin()} />}</section></StoreShell>;
}

function InfoTile({ icon, title, body }: { icon: React.ReactNode; title: string; body: string }) { return <div className="glass-panel p-6"><div className="w-10 h-10 flex items-center justify-center border border-cyan-300/25 text-cyan-300 mb-5">{icon}</div><h3 className="font-display text-lg text-white mb-2">{title}</h3><p className="text-sm leading-6 text-slate-500">{body}</p></div>; }

function EmptyState({ title, body, action }: { title: string; body: string; action?: React.ReactNode }) { return <div className="empty-state"><div className="empty-cross">+</div><h3 className="font-display text-xl text-white mb-2">{title}</h3><p className="text-sm text-slate-500 max-w-md mx-auto leading-6">{body}</p>{action && <div className="mt-6">{action}</div>}</div>; }
function GridSkeleton() { return <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">{Array.from({ length: 4 }).map((_, i) => <div key={i} className="product-card animate-pulse"><div className="h-56 bg-white/5" /><div className="p-4"><div className="h-4 bg-white/10 w-2/3 mb-4" /><div className="h-3 bg-white/5 w-1/3" /></div></div>)}</div>; }

export function CatalogPage({ category }: { category: CategoryKey }) {
  const { isAuthenticated } = useAuth();
  const [search, setSearch] = useState("");
  const [sort, setSort] = useState<"menu" | "newest" | "price-low" | "price-high" | "name-asc" | "name-desc">(category === "GAME" ? "menu" : "newest");
  const query = useMemo(() => ({ category, search: search || undefined, sort, limit: 48 }), [category, search, sort]);
  const products = trpc.catalog.list.useQuery(query);
  const favoriteIds = trpc.customer.favoriteIds.useQuery(undefined, { enabled: isAuthenticated, retry: false });
  return <StoreShell><div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-14"><div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-10"><div><div className="eyebrow mb-3">CATALOG / {CATEGORY_LABELS[category].toUpperCase()}</div><h1 className="font-display text-4xl md:text-6xl text-white tracking-tight">{CATEGORY_LABELS[category]}</h1><p className="text-slate-500 mt-3 max-w-xl">Browse legitimate listings with availability controlled by the store team.</p></div><div className="flex flex-wrap gap-2"><Link href="/search"><Button variant="outline" className="border-white/15"><Search className="w-4 h-4 mr-2" /> Global search</Button></Link><select value={sort} onChange={(e) => setSort(e.target.value as typeof sort)} className="field-select"><option value="menu">Featured / menu order</option><option value="newest">Newest</option><option value="name-asc">Name A–Z</option><option value="name-desc">Name Z–A</option><option value="price-low">Price low–high</option><option value="price-high">Price high–low</option></select></div></div><div className="filter-bar mb-8"><Search className="w-4 h-4 text-slate-500" /><Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder={`Search ${CATEGORY_LABELS[category].toLowerCase()} by name, genre, or platform`} className="bg-transparent border-0 focus-visible:ring-0" /></div>{products.isLoading ? <GridSkeleton /> : products.data?.length ? <ProductGrid products={products.data} favoriteIds={favoriteIds.data} onNeedAuth={() => startLogin()} /> : <EmptyState title="No matching signal" body="Try another search, or send a request if the title you want is not currently listed." action={<Link href="/request"><Button className="neon-button">Request a title</Button></Link>} />}</div></StoreShell>;
}

export function SearchPage() {
  const [search, setSearch] = useState("");
  const { isAuthenticated } = useAuth();
  const products = trpc.catalog.list.useQuery({ search, limit: 48 }, { enabled: search.length > 1 });
  return <StoreShell><div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-16"><div className="max-w-3xl mb-10"><div className="eyebrow mb-3">GLOBAL SEARCH</div><h1 className="font-display text-5xl text-white tracking-tight">Find the title.</h1><p className="text-slate-500 mt-4">Search across games, movies, series, and hardware. Search only returns catalog records — never fabricated metadata.</p></div><div className="search-hero mb-12"><Search className="w-6 h-6 text-cyan-300" /><Input autoFocus value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Try Cyberpunk, racing, SSD..." className="bg-transparent border-0 text-lg focus-visible:ring-0" /></div>{search.length < 2 ? <EmptyState title="Your search starts here" body="Enter at least two characters to search the catalog." /> : products.isLoading ? <GridSkeleton /> : <ProductGrid products={products.data ?? []} favoriteIds={isAuthenticated ? [] : undefined} onNeedAuth={() => startLogin()} />}</div></StoreShell>;
}

export function ProductPage() {
  const [, params] = useRoute("/products/:slug");
  const product = trpc.catalog.get.useQuery({ slug: params?.slug ?? "" });
  const { isAuthenticated, user } = useAuth();
  const favs = trpc.customer.favoriteIds.useQuery(undefined, { enabled: isAuthenticated, retry: false });
  if (product.isLoading) return <StoreShell><div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-20"><GridSkeleton /></div></StoreShell>;
  if (!product.data) return <StoreShell><div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-20"><EmptyState title="Product not found" body="This listing may have been removed or has not been configured yet." action={<Link href="/games"><Button variant="outline">Back to catalog</Button></Link>} /></div></StoreShell>;
  const item = product.data;
  const available = item.availability && item.price !== null;
  return <StoreShell><div className="product-detail"><div className="detail-art" style={{ backgroundImage: `url(${item.backgroundImage ?? HERO_ART})` }} /><div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-14 relative"><Link href={`/${item.category === "GAME" ? "games" : item.category === "MOVIE" ? "movies" : item.category === "TV_SHOW" ? "series" : "hardware"}`} className="inline-flex items-center gap-2 text-sm text-slate-400 hover:text-white mb-12"><ArrowLeft className="w-4 h-4" /> Back to catalog</Link><div className="grid lg:grid-cols-[.8fr_1.2fr] gap-12 items-end"><div className="detail-cover"><img src={item.coverImage ?? HERO_ART} alt={`${item.name} abstract cover`} /></div><div className="max-w-2xl"><div className="eyebrow mb-4">{CATEGORY_LABELS[item.category]} / LISTING {String(item.id).padStart(3, "0")}</div><h1 className="font-display text-5xl md:text-7xl text-white font-bold tracking-tight leading-[.95]">{item.name}</h1><div className="rich-content mt-6" dangerouslySetInnerHTML={{ __html: item.description ?? "<p>Metadata will be added by the store team when this listing is configured. No unverified details are shown as fact.</p>" }} /><div className="flex items-center gap-4 mt-8"><span className="text-2xl text-cyan-300 font-semibold">{formatMoney(item.price)}</span>{item.imdbRating && <span className="badge badge-status">IMDb {item.imdbRating}/10</span>}<span className={cn("badge", available ? "badge-on" : "badge-off")}>{available ? "Available" : "Not configured"}</span></div><div className="flex flex-wrap gap-3 mt-8"><ProductActions product={item} available={available} favorited={favs.data?.includes(item.id) ?? false} onNeedAuth={() => startLogin()} />{user?.role === "admin" && <Link href={`/admin/products?edit=${item.id}`}><Button variant="outline" className="h-12 px-5 border-cyan-300/30 text-cyan-200"><Settings className="w-4 h-4 mr-2" /> Edit full listing</Button></Link>}</div><div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mt-12">{[["PLATFORM", item.platform], ["GENRE", item.genre], ["SIZE", item.size], ["RELEASE", item.releaseDate]].map(([label, value]) => <div key={label} className="detail-stat"><span>{label}</span><strong>{value || "Not configured"}</strong></div>)}</div></div></div></div></div>{Array.isArray(item.gallery) && item.gallery.length > 0 && <div className="max-w-[1440px] mx-auto px-5 lg:px-10 pt-10"><SectionHeading eyebrow="GALLERY" title="Inside the listing" /><div className="grid grid-cols-2 md:grid-cols-4 gap-4">{item.gallery.map((url) => typeof url === "string" ? <img key={url} src={url} alt={`${item.name} gallery`} className="w-full aspect-video object-cover border border-white/10" /> : null)}</div></div>}<div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-20"><SectionHeading eyebrow="MORE TO EXPLORE" title="Keep scanning" /><div className="grid md:grid-cols-3 gap-5"><InfoTile icon={<Gamepad2 />} title="Games" body="A wide catalog of legitimate PC listings, with price and availability set by the store team." /><InfoTile icon={<Star />} title="Cinema" body="Movie and series requests are welcome when a listing is not yet available." /><InfoTile icon={<Cpu />} title="Hardware" body="Physical stock is validated before an order can be submitted." /></div></div></StoreShell>;
}

function ProductActions({ product, available, favorited, onNeedAuth }: { product: Product; available: boolean; favorited: boolean; onNeedAuth: () => void }) { const { isAuthenticated } = useAuth(); const [, navigate] = useLocation(); const add = trpc.customer.addToCart.useMutation({ onSuccess: () => { if (product.category === "HARDWARE") navigate("/checkout"); else toast.success("Added to cart"); }, onError: (e) => toast.error(e.message) }); const fav = trpc.customer.toggleFavorite.useMutation({ onSuccess: () => toast.success(favorited ? "Removed from favorites" : "Saved to favorites") }); return <><Button disabled={!available || add.isPending} onClick={() => { if (!isAuthenticated) return onNeedAuth(); add.mutate({ productId: product.id, quantity: 1 }); }} className="neon-button h-12 px-6">{available ? <><ShoppingBag className="w-4 h-4 mr-2" /> {product.category === "HARDWARE" ? "Buy hardware" : "Add to cart"}</> : "Unavailable"}</Button><Button variant="outline" onClick={() => { if (!isAuthenticated) return onNeedAuth(); fav.mutate({ productId: product.id }); }} className={cn("h-12 px-5 border-white/20", favorited && "text-pink-300 border-pink-300/30")}><Heart className={cn("w-4 h-4 mr-2", favorited && "fill-current")} /> {favorited ? "Saved" : "Save"}</Button></>; }

export function CartPage() { const { isAuthenticated } = useAuth(); const cart = trpc.customer.cart.useQuery(undefined, { enabled: isAuthenticated, retry: false }); const update = trpc.customer.updateCartItem.useMutation({ onSuccess: () => cart.refetch(), onError: (e) => toast.error(e.message) }); const remove = trpc.customer.removeCartItem.useMutation({ onSuccess: () => cart.refetch() }); if (!isAuthenticated) return <StoreShell><div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-24"><LoginPanel title="Your cart is private" /></div></StoreShell>; return <StoreShell><div className="max-w-[1100px] mx-auto px-5 lg:px-10 py-16"><div className="eyebrow mb-3">CHECKOUT / CART</div><h1 className="font-display text-5xl text-white mb-10">Your loadout.</h1>{cart.isLoading ? <GridSkeleton /> : !cart.data?.items.length ? <EmptyState title="Your cart is quiet" body="Add a configured listing to start an order." action={<Link href="/games"><Button className="neon-button">Browse games</Button></Link>} /> : <div className="grid lg:grid-cols-[1fr_340px] gap-8 items-start"><div className="space-y-3">{cart.data.items.map((item) => <div key={item.id} className="glass-panel p-4 flex gap-4 items-center"><img src={item.product.coverImage ?? HERO_ART} alt="" className="w-20 h-20 object-cover" /><div className="flex-1 min-w-0"><div className="eyebrow mb-1">{CATEGORY_LABELS[item.product.category]}</div><h3 className="font-display text-white truncate">{item.product.name}</h3><p className="text-sm text-cyan-300 mt-1">{formatMoney(item.product.price)}</p>{!item.purchasable && <p className="text-xs text-amber-300 mt-2">Unavailable or quantity exceeds validated stock.</p>}</div><div className="flex items-center gap-2"><Button variant="outline" size="icon" className="h-8 w-8" onClick={() => update.mutate({ itemId: item.id, quantity: Math.max(item.quantity - 1, 0) })}>−</Button><span className="w-5 text-center text-sm">{item.quantity}</span><Button variant="outline" size="icon" className="h-8 w-8" onClick={() => update.mutate({ itemId: item.id, quantity: item.quantity + 1 })}>+</Button></div><div className="text-right w-28"><div className="text-white font-semibold">{item.lineTotal === null ? "—" : formatMoney(item.lineTotal)}</div><button onClick={() => remove.mutate({ itemId: item.id })} className="text-xs text-slate-600 hover:text-red-300 mt-2"><Trash2 className="w-3 h-3 inline mr-1" />Remove</button></div></div>)}</div><div className="glass-panel p-6 sticky top-24"><div className="eyebrow mb-5">ORDER SUMMARY</div><div className="flex justify-between text-sm text-slate-400 mb-3"><span>Subtotal</span><span>{formatMoney(cart.data.subtotal)}</span></div><div className="border-t border-white/10 pt-4 flex justify-between text-white font-semibold"><span>Total</span><span>{formatMoney(cart.data.total)}</span></div><p className="text-xs text-slate-600 leading-5 mt-5">Final totals are revalidated server-side at checkout. Requests and WhatsApp conversations never count as payment.</p><Link href="/checkout"><Button disabled={cart.data.hasUnavailableItems} className="neon-button w-full mt-6">Continue to checkout <ArrowRight className="w-4 h-4 ml-2" /></Button></Link></div></div>}</div></StoreShell>; }

export function CheckoutPage() { const { isAuthenticated } = useAuth(); const { language } = useLanguage(); const cart = trpc.customer.cart.useQuery(undefined, { enabled: isAuthenticated, retry: false }); const storage = trpc.catalog.storageOptions.useQuery(); const [choice, setChoice] = useState("OWN_HDD"); const [orderId, setOrderId] = useState<number | null>(null); const [whatsappRedirected, setWhatsappRedirected] = useState(false); const whatsappInput = useMemo(() => ({ orderId: orderId ?? 0, language }), [orderId, language]); const whatsapp = trpc.customer.whatsapp.useQuery(whatsappInput, { enabled: Boolean(orderId), retry: false }); useEffect(() => { if (!whatsapp.data?.url || whatsappRedirected) return; const opened = window.open(whatsapp.data.url, "_blank", "noopener,noreferrer"); if (opened) setWhatsappRedirected(true); else toast.error("WhatsApp could not open automatically. Use Copy order details below."); }, [whatsapp.data?.url, whatsappRedirected]); const create = trpc.customer.checkout.useMutation({ onSuccess: (data) => { setOrderId(data?.order?.id ?? null); toast.success("Order submitted — opening WhatsApp"); }, onError: (e) => toast.error(e.message) }); if (!isAuthenticated) return <StoreShell><div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-24"><LoginPanel /></div></StoreShell>; if (orderId) return <StoreShell><div className="max-w-2xl mx-auto px-5 py-24"><div className="glass-panel p-8 text-center"><div className="success-orb"><Check /></div><div className="eyebrow mt-6 mb-3">ORDER / WHATSAPP HANDOFF</div><h1 className="font-display text-4xl text-white">Order submitted successfully.</h1><p className="text-slate-400 mt-4 leading-7">Order <span className="text-cyan-300">#{orderId}</span> is pending acceptance. WhatsApp is opening with your order details already written. If it does not open automatically, use the button below. WhatsApp is communication-only and never confirms payment.</p>{whatsapp.isLoading || whatsappRedirected ? <div className="flex items-center justify-center gap-2 text-sm text-slate-400 mt-8"><Loader2 className="w-4 h-4 animate-spin text-cyan-300" /> Opening WhatsApp with your cart details…</div> : whatsapp.data?.url ? <a href={whatsapp.data.url} target="_blank" rel="noreferrer" className="inline-flex mt-8"><Button className="neon-button">Continue on WhatsApp <ExternalLink className="w-4 h-4 ml-2" /></Button></a> : <p className="text-xs text-amber-300/80 mt-8">The store has not configured a WhatsApp business number yet. You can still track the order below.</p>}{whatsapp.data?.message && <Button type="button" variant="outline" className="mt-4 border-white/15" onClick={async () => { try { await navigator.clipboard.writeText(whatsapp.data?.message ?? ""); toast.success("Order details copied"); } catch { toast.error("Copy failed — select the message manually from WhatsApp"); } }}><Copy className="w-4 h-4 mr-2" /> Copy order details</Button>}<div className="flex flex-wrap justify-center gap-3 mt-8"><Link href={`/order/${orderId}`}><Button variant="outline" className="border-white/15">Track order</Button></Link><Link href="/"><Button variant="outline" className="border-white/15">Keep browsing</Button></Link></div></div></div></StoreShell>; return <StoreShell><div className="max-w-[1000px] mx-auto px-5 lg:px-10 py-16"><div className="eyebrow mb-3">CHECKOUT / HANDOFF</div><h1 className="font-display text-5xl text-white">How should we prepare it?</h1><p className="text-slate-500 mt-4 max-w-xl">Choose the storage path. Hardware options are shown only when live inventory says they are available.</p><div className="grid md:grid-cols-2 gap-4 mt-10"><button onClick={() => setChoice("OWN_HDD")} className={cn("choice-card text-left", choice === "OWN_HDD" && "selected")}><div className="choice-index">01</div><h2 className="font-display text-xl text-white">I have my own hard drive</h2><p className="text-sm text-slate-500 mt-2 leading-6">We will include that preference in the order discussion. WhatsApp remains communication only.</p>{choice === "OWN_HDD" && <Check className="choice-check" />}</button><button onClick={() => setChoice(storage.data?.[0] ? `PRODUCT_${storage.data[0].product.id}` : "NEED_HDD")} className={cn("choice-card text-left", choice !== "OWN_HDD" && "selected")}><div className="choice-index">02</div><h2 className="font-display text-xl text-white">I need a hard drive</h2><p className="text-sm text-slate-500 mt-2 leading-6">Select from hardware inventory that is actually available.</p>{choice !== "OWN_HDD" && <Check className="choice-check" />}</button></div>{choice !== "OWN_HDD" && <div className="mt-6 space-y-2">{storage.data?.length ? storage.data.map(({ product, stock }) => <button key={product.id} onClick={() => setChoice(`PRODUCT_${product.id}`)} className={cn("storage-row", choice === `PRODUCT_${product.id}` && "selected")}><span><span className="font-medium text-white">{product.name}</span><span className="block text-xs text-slate-500 mt-1">{stock.stock - stock.reserved} available</span></span><span className="text-cyan-300">{formatMoney(product.price)}</span></button>) : <EmptyState title="No storage inventory available" body="The store team has not made any storage option available yet. Choose your own hard drive or return when inventory is configured." />}</div>}<div className="glass-panel p-6 mt-10 flex flex-col sm:flex-row justify-between gap-6 items-start sm:items-center"><div><div className="eyebrow mb-2">SERVER-VALIDATED TOTAL</div><div className="text-2xl text-white font-semibold">{formatMoney(cart.data?.total)}</div><p className="text-xs text-slate-600 mt-2">{cart.data?.items.length ?? 0} line items · recalculated at submit</p></div><Button disabled={!cart.data?.items.length || create.isPending || (choice !== "OWN_HDD" && !choice.startsWith("PRODUCT_"))} onClick={() => create.mutate({ storageRequirement: choice })} className="neon-button h-12 px-6">{create.isPending ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" />Submitting order…</> : <>Submit WhatsApp order <Send className="w-4 h-4 ml-2" /></>}</Button></div></div></StoreShell>; }
export function AccountPage() { const accountItems: Array<[string, string, React.ElementType]> = [["home", "Overview", LayoutDashboard], ["orders", "Orders", Package], ["favorites", "Favorites", Heart], ["requests", "Requests", ClipboardList], ["settings", "Settings", Settings]]; const { user, isAuthenticated, logout } = useAuth(); const [location] = useLocation(); if (!isAuthenticated) return <StoreShell><div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-24"><LoginPanel /></div></StoreShell>; const tab = location.split("/")[2] ?? "home"; return <StoreShell><div className="max-w-[1200px] mx-auto px-5 lg:px-10 py-14"><div className="flex flex-col md:flex-row md:items-end justify-between gap-5 mb-10"><div><div className="eyebrow mb-3">ACCOUNT / PRIVATE CHANNEL</div><h1 className="font-display text-5xl text-white">Welcome back, {user?.name?.split(" ")[0] ?? "player"}.</h1></div><Button variant="outline" onClick={logout} className="border-white/15 self-start">Sign out</Button></div><div className="grid lg:grid-cols-[220px_1fr] gap-8"><aside className="space-y-1">{accountItems.map(([key, label, Icon]) => <Link key={String(key)} href={key === "home" ? "/account" : `/account/${key}`} className={cn("account-nav", tab === key && "active")}><Icon className="w-4 h-4" />{label}</Link>)}</aside><div>{tab === "home" && <AccountOverview userName={user?.name ?? ""} />}{tab === "orders" && <OrdersPanel />}{tab === "favorites" && <FavoritesPanel />}{tab === "requests" && <RequestsPanel />}{tab === "settings" && <SettingsPanel />}</div></div></div></StoreShell>; }

function AccountOverview({ userName }: { userName: string }) { const orders = trpc.customer.orders.useQuery(); const requests = trpc.requests.mine.useQuery(); const notifications = trpc.customer.notifications.useQuery(); const analytics = trpc.customer.analytics.useQuery({ month: new Date().toISOString().slice(0, 7) }); return <div className="space-y-6"><div className="grid sm:grid-cols-3 gap-4"><Metric label="Orders" value={String(orders.data?.length ?? 0)} /><Metric label="Open requests" value={String(requests.data?.filter((x) => x.status !== "COMPLETED").length ?? 0)} /><Metric label="Unread signals" value={String(notifications.data?.filter((x) => !x.read).length ?? 0)} /></div><div className="glass-panel p-6"><SectionHeading eyebrow="MONTHLY PULSE" title="Completed activity" /><div className="grid grid-cols-2 md:grid-cols-4 gap-4">{[["Orders", analytics.data?.orders ?? 0], ["Products", analytics.data?.productsPurchased ?? 0], ["Games", analytics.data?.games ?? 0], ["Hardware", analytics.data?.hardware ?? 0]].map(([label, value]) => <div key={String(label)} className="detail-stat"><span>{label}</span><strong>{String(value)}</strong></div>)}</div><p className="text-xs text-slate-600 mt-6">Only completed orders count toward purchase analytics. Requests are tracked separately.</p></div><div className="glass-panel p-6"><div className="flex items-center gap-3"><div className="w-10 h-10 border border-cyan-300/30 flex items-center justify-center text-cyan-300"><CircleUserRound /></div><div><div className="eyebrow">PROFILE</div><div className="text-white mt-1">{userName || "Account holder"}</div></div></div></div></div>; }
function Metric({ label, value }: { label: string; value: string }) { return <div className="glass-panel p-5"><div className="eyebrow mb-3">{label}</div><div className="text-3xl font-display text-white">{value}</div></div>; }
function OrdersPanel() { const orders = trpc.customer.orders.useQuery(); return <div><SectionHeading eyebrow="ACCOUNT / ORDERS" title="Order history" />{orders.data?.length ? <div className="space-y-3">{orders.data.map((order) => <Link key={order.id} href={`/order/${order.id}`} className="glass-panel p-5 flex flex-wrap gap-4 items-center justify-between hover:border-cyan-300/30 transition-colors"><div><div className="eyebrow mb-2">ORDER #{order.id}</div><div className="text-white font-display">{formatDate(order.createdAt)}</div></div><Badge className="badge-status">{ORDER_STATUS_LABELS[order.status]}</Badge><div className="text-cyan-300 font-semibold">{formatMoney(order.total)}</div><ArrowRight className="w-4 h-4 text-slate-600" /></Link>)}</div> : <EmptyState title="No orders yet" body="Your completed and in-progress orders will appear here." action={<Link href="/games"><Button className="neon-button">Browse catalog</Button></Link>} />}</div>; }
function FavoritesPanel() { const favs = trpc.customer.favorites.useQuery(); return <div><SectionHeading eyebrow="ACCOUNT / FAVORITES" title="Saved for later" />{favs.data?.length ? <ProductGrid products={favs.data.map((x) => x.product)} favoriteIds={favs.data.map((x) => x.product.id)} onNeedAuth={() => startLogin()} /> : <EmptyState title="Nothing saved yet" body="Tap the heart on any product to build a private shortlist." />}</div>; }
function RequestsPanel() { const requests = trpc.requests.mine.useQuery(); return <div><SectionHeading eyebrow="ACCOUNT / REQUESTS" title="Your requests" action={<Link href="/request"><Button className="neon-button"><Plus className="w-4 h-4 mr-2" /> New request</Button></Link>} />{requests.data?.length ? <div className="space-y-3">{requests.data.map((request) => <Link key={request.id} href={`/account/requests/${request.id}`} className="glass-panel p-5 flex flex-wrap gap-4 items-center justify-between"><div><div className="eyebrow mb-2">{request.requestCode}</div><div className="text-white font-display">{request.title}</div></div><span className="text-xs text-slate-500">{request.type}</span><Badge className="badge-status">{REQUEST_STATUS_LABELS[request.status]}</Badge><ArrowRight className="w-4 h-4 text-slate-600" /></Link>)}</div> : <EmptyState title="No requests in orbit" body="Tell us what title should be next." action={<Link href="/request"><Button className="neon-button">Open Request Center</Button></Link>} />}</div>; }
function SettingsPanel() { const { user } = useAuth(); return <div><SectionHeading eyebrow="ACCOUNT / SETTINGS" title="Identity settings" /><div className="glass-panel p-6 space-y-5"><div><label className="field-label">Full name</label><Input value={user?.name ?? ""} readOnly className="field-input" /></div><div><label className="field-label">Email</label><Input value={user?.email ?? ""} readOnly className="field-input" /></div><div className="border-t border-white/10 pt-5 text-sm text-slate-500">Authentication and email verification are managed by the secure project identity provider.</div></div></div>; }

export function OrderPage() { const [, params] = useRoute("/order/:id"); const { isAuthenticated } = useAuth(); const id = Number(params?.id); const order = trpc.customer.order.useQuery({ orderId: id }, { enabled: isAuthenticated && Number.isInteger(id), refetchInterval: 10000 }); const whatsapp = trpc.customer.whatsapp.useQuery({ orderId: id }, { enabled: Boolean(order.data) }); if (!isAuthenticated) return <StoreShell><div className="max-w-[1440px] mx-auto px-5 py-24"><LoginPanel /></div></StoreShell>; if (order.isLoading) return <StoreShell><div className="max-w-[900px] mx-auto px-5 py-20"><GridSkeleton /></div></StoreShell>; if (!order.data) return <StoreShell><div className="max-w-[900px] mx-auto px-5 py-20"><EmptyState title="Order not found" body="This order does not exist or does not belong to this account." /></div></StoreShell>; const currentIndex = ["PENDING_ACCEPTANCE", "ACCEPTED", "PREPARING", "READY", "COMPLETED"].indexOf(order.data.order.status); return <StoreShell><div className="max-w-[1000px] mx-auto px-5 lg:px-10 py-16"><div className="flex flex-wrap justify-between gap-5 items-start mb-10"><div><div className="eyebrow mb-3">ORDER #{order.data.order.id} / LIVE TIMELINE</div><h1 className="font-display text-5xl text-white">{ORDER_STATUS_LABELS[order.data.order.status]}</h1><p className="text-slate-500 mt-3">Submitted {formatDate(order.data.order.createdAt)} · updates refresh automatically.</p></div><Badge className="badge-status text-sm px-4 py-2">{order.data.order.status}</Badge></div><div className="glass-panel p-6 mb-6"><div className="timeline">{["PENDING_ACCEPTANCE", "ACCEPTED", "PREPARING", "READY", "COMPLETED"].map((status, index) => <div key={status} className={cn("timeline-item", index <= currentIndex && order.data?.order.status !== "REJECTED" && order.data?.order.status !== "CANCELLED" && "done", (status === order.data?.order.status) && "current")}><div className="timeline-dot">{index <= currentIndex && order.data?.order.status !== "REJECTED" && order.data?.order.status !== "CANCELLED" ? <Check className="w-3 h-3" /> : index + 1}</div><div><div className="text-sm text-white">{ORDER_STATUS_LABELS[status as keyof typeof ORDER_STATUS_LABELS]}</div><div className="text-xs text-slate-600 mt-1">{order.data?.history.find((x) => x.status === status) ? formatDate(order.data.history.find((x) => x.status === status)?.createdAt) : "Awaiting update"}</div></div></div>)}</div>{(order.data.order.status === "REJECTED" || order.data.order.status === "CANCELLED") && <div className="mt-5 p-4 border border-red-300/20 bg-red-300/5 text-sm text-red-200">This order is {order.data.order.status.toLowerCase()}. No further transitions are available.</div>}</div><div className="grid md:grid-cols-[1fr_320px] gap-6"><div className="glass-panel p-6"><div className="eyebrow mb-5">LINE ITEMS</div>{order.data.items.map((item) => <div key={item.id} className="flex justify-between gap-4 py-3 border-b border-white/5 last:border-0"><div><div className="text-white">{item.productName}</div><div className="text-xs text-slate-500 mt-1">Qty {item.quantity} × {formatMoney(item.unitPrice)}</div></div><div className="text-cyan-300">{formatMoney(item.subtotal)}</div></div>)}<div className="flex justify-between pt-5 text-white font-semibold"><span>Total</span><span>{formatMoney(order.data.order.total)}</span></div></div><div className="space-y-6"><div className="glass-panel p-6"><div className="eyebrow mb-3">STORAGE</div><div className="text-white">{order.data.order.storageRequirement === "OWN_HDD" ? "Own hard drive" : order.data.order.storageRequirement ?? "Not specified"}</div></div><div className="glass-panel p-6"><div className="eyebrow mb-3">DISCUSS ORDER</div><p className="text-xs text-slate-500 leading-5">WhatsApp opens a prefilled message for discussion only. It never confirms payment or changes status.</p>{whatsapp.data && <a href={whatsapp.data.url} target="_blank" rel="noreferrer" className="mt-4 inline-flex"><Button className="neon-button"><ExternalLink className="w-4 h-4 mr-2" /> Continue to WhatsApp</Button></a>}</div></div></div></div></StoreShell>; }

export function RequestCenterPage() { const cards: Array<[string, string, string, string, React.ElementType]> = [["GAME", "Request a game", "Platform, year, and any identifiers you know.", "/request/game", Gamepad2], ["MOVIE", "Request a movie", "Use an IMDb URL or ID when available.", "/request/movie", Star], ["SERIES", "Request a series", "Tell us whether you need the full series or specific seasons.", "/request/series", ClipboardList]]; return <StoreShell><div className="max-w-[1200px] mx-auto px-5 lg:px-10 py-16"><div className="max-w-2xl mb-12"><div className="eyebrow mb-3">REQUEST CENTER</div><h1 className="font-display text-5xl md:text-6xl text-white tracking-tight">If it is not here,<br /><span className="text-gradient">send a signal.</span></h1><p className="text-slate-500 mt-5 leading-7">Requests stay separate from purchases and revenue. Give the team enough detail to identify the right title and edition.</p></div><div className="grid md:grid-cols-3 gap-5">{cards.map(([tag, title, body, href, Icon]) => <Link key={href} href={href} className="request-card"><span className="eyebrow">{tag}</span><Icon className="w-8 h-8 text-cyan-300 my-8" /><h2 className="font-display text-2xl text-white">{title}</h2><p className="text-sm text-slate-500 leading-6 mt-3">{body}</p><span className="mt-8 inline-flex items-center gap-2 text-sm text-cyan-300">Open form <ArrowRight className="w-4 h-4" /></span></Link>)}</div></div></StoreShell>; }

export function RequestFormPage({ type }: { type: "GAME" | "MOVIE" | "SERIES" }) { const { isAuthenticated } = useAuth(); const create = trpc.requests.create.useMutation({ onSuccess: (data) => { toast.success("Request submitted"); window.location.href = `/account/requests/${data?.request?.id ?? ""}`; }, onError: (e) => toast.error(e.message) }); const [form, setForm] = useState({ title: "", imdbId: "", imdbUrl: "", platform: "", releaseYear: "", quality: "", requestScope: "FULL_SERIES", seasons: "", notes: "" }); if (!isAuthenticated) return <StoreShell><div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-24"><LoginPanel title="Requests are tied to your account" /></div></StoreShell>; const set = (key: keyof typeof form, value: string) => setForm((current) => ({ ...current, [key]: value })); return <StoreShell><div className="max-w-[820px] mx-auto px-5 lg:px-10 py-16"><Link href="/request" className="inline-flex items-center gap-2 text-sm text-slate-400 hover:text-white mb-10"><ArrowLeft className="w-4 h-4" /> Request Center</Link><div className="eyebrow mb-3">REQUEST / {type}</div><h1 className="font-display text-5xl text-white">Tell us what to find.</h1><p className="text-slate-500 mt-4 mb-10">We store your provided identifiers exactly as submitted. No IMDb data is invented or scraped without a configured legitimate API.</p><form className="glass-panel p-6 md:p-8 space-y-5" onSubmit={(e) => { e.preventDefault(); create.mutate({ type, title: form.title, imdbId: form.imdbId || undefined, imdbUrl: form.imdbUrl || undefined, platform: form.platform || undefined, releaseYear: form.releaseYear ? Number(form.releaseYear) : undefined, quality: form.quality || undefined, requestScope: type === "SERIES" ? form.requestScope : undefined, seasons: type === "SERIES" && form.requestScope === "SPECIFIC_SEASONS" ? form.seasons : undefined, notes: form.notes || undefined }); }}><div className="grid md:grid-cols-2 gap-5"><Field label={`${type === "GAME" ? "Game" : type === "MOVIE" ? "Movie" : "Series"} name`} required><Input required value={form.title} onChange={(e) => set("title", e.target.value)} className="field-input" /></Field><Field label="Release year"><Input type="number" value={form.releaseYear} onChange={(e) => set("releaseYear", e.target.value)} className="field-input" /></Field></div>{type === "GAME" && <Field label="Platform"><Input placeholder="PC, PlayStation, Xbox..." value={form.platform} onChange={(e) => set("platform", e.target.value)} className="field-input" /></Field>}{type !== "GAME" && <div className="grid md:grid-cols-2 gap-5"><Field label="IMDb ID"><Input placeholder="tt1234567" value={form.imdbId} onChange={(e) => set("imdbId", e.target.value)} className="field-input" /></Field><Field label="IMDb URL"><Input placeholder="https://www.imdb.com/title/tt..." value={form.imdbUrl} onChange={(e) => set("imdbUrl", e.target.value)} className="field-input" /></Field></div>}{type !== "GAME" && <Field label="Preferred quality"><Input placeholder="1080p, 4K, Blu-ray..." value={form.quality} onChange={(e) => set("quality", e.target.value)} className="field-input" /></Field>}{type === "SERIES" && <div className="grid md:grid-cols-2 gap-5"><Field label="Scope"><select value={form.requestScope} onChange={(e) => set("requestScope", e.target.value)} className="field-select w-full"><option value="FULL_SERIES">Full series</option><option value="SPECIFIC_SEASONS">Specific seasons</option></select></Field>{form.requestScope === "SPECIFIC_SEASONS" && <Field label="Season numbers"><Input placeholder="1, 3" value={form.seasons} onChange={(e) => set("seasons", e.target.value)} className="field-input" /></Field>}</div>}<Field label="Additional details / notes"><Textarea rows={5} value={form.notes} onChange={(e) => set("notes", e.target.value)} className="field-input" /></Field><div className="flex items-center justify-between gap-4 pt-3"><span className="text-xs text-slate-600">Request ID is generated by the server.</span><Button type="submit" disabled={create.isPending} className="neon-button">Submit request <Send className="w-4 h-4 ml-2" /></Button></div></form></div></StoreShell>; }
function Field({ label, required, children }: { label: string; required?: boolean; children: React.ReactNode }) { return <div><label className="field-label">{label}{required && <span className="text-cyan-300 ml-1">*</span>}</label>{children}</div>; }

export function RequestDetailPage() { const [, params] = useRoute("/account/requests/:id"); const { isAuthenticated } = useAuth(); const request = trpc.requests.get.useQuery({ requestId: Number(params?.id) }, { enabled: isAuthenticated }); if (!isAuthenticated) return <StoreShell><div className="max-w-[1440px] mx-auto px-5 py-24"><LoginPanel /></div></StoreShell>; if (!request.data) return <StoreShell><div className="max-w-[900px] mx-auto px-5 py-20"><EmptyState title="Request not found" body="This request does not exist or is not linked to this account." /></div></StoreShell>; return <StoreShell><div className="max-w-[900px] mx-auto px-5 lg:px-10 py-16"><Link href="/account/requests" className="inline-flex items-center gap-2 text-sm text-slate-400 hover:text-white mb-10"><ArrowLeft className="w-4 h-4" /> Your requests</Link><div className="flex flex-wrap items-start justify-between gap-5 mb-10"><div><div className="eyebrow mb-3">{request.data.request.requestCode}</div><h1 className="font-display text-5xl text-white">{request.data.request.title}</h1><p className="text-slate-500 mt-3">Submitted {formatDate(request.data.request.createdAt)} · {request.data.request.type}</p></div><Badge className="badge-status">{REQUEST_STATUS_LABELS[request.data.request.status]}</Badge></div><div className="glass-panel p-6"><div className="eyebrow mb-5">STATUS TIMELINE</div>{request.data.history.map((entry, index) => <div key={entry.id} className="flex gap-4 py-4 border-b border-white/5 last:border-0"><div className="timeline-dot done">{index + 1}</div><div><div className="text-white">{REQUEST_STATUS_LABELS[entry.status]}</div><div className="text-xs text-slate-600 mt-1">{formatDate(entry.createdAt)}</div>{entry.note && <p className="text-sm text-slate-500 mt-2">{entry.note}</p>}</div></div>)}</div>{request.data.request.adminNotes && <div className="glass-panel p-6 mt-5"><div className="eyebrow mb-3">TEAM NOTE</div><p className="text-slate-300 leading-7">{request.data.request.adminNotes}</p></div>}</div></StoreShell>; }

export function AdminAccountPage() { const { user, isAuthenticated, logout } = useAuth(); if (!isAuthenticated) return <StoreShell><div className="max-w-[1440px] mx-auto px-5 py-24"><LoginPanel title="Admin access required" body="Sign in with the authorized administrator identity to open the operations account." /></div></StoreShell>; if (!user || user.role !== "admin") return <StoreShell><div className="max-w-[900px] mx-auto px-5 py-24"><EmptyState title="Access denied" body="This account area is restricted to administrator identities." action={<Link href="/"><Button variant="outline">Return to storefront</Button></Link>} /></div></StoreShell>; return <StoreShell><div className="max-w-[1240px] mx-auto px-5 lg:px-10 py-12"><div className="flex flex-col lg:flex-row gap-8"><aside className="lg:w-64 shrink-0"><div className="admin-account-card"><div className="admin-avatar"><ShieldCheck className="w-7 h-7" /></div><div className="eyebrow mt-5">ADMIN IDENTITY</div><h1 className="font-display text-2xl text-white mt-2 break-words">{user.name || "Store administrator"}</h1><p className="text-xs text-slate-500 mt-2 break-all">{user.email || user.openId}</p><div className="admin-role-chip mt-5"><span className="signal-dot" /> ADMIN / OWNER ACCESS</div></div><div className="mt-4 space-y-1"><Link href="/admin" className="account-nav active"><LayoutDashboard className="w-4 h-4" /> Command center</Link><Link href="/admin/orders" className="account-nav"><Package className="w-4 h-4" /> Order operations</Link><Link href="/admin/products" className="account-nav"><ShoppingBag className="w-4 h-4" /> Catalog control</Link><Link href="/admin/settings" className="account-nav"><Settings className="w-4 h-4" /> System settings</Link></div></aside><main className="flex-1 min-w-0"><div className="eyebrow mb-3">ACCOUNT / ADMIN CONTROL</div><div className="flex flex-wrap items-end justify-between gap-5 mb-8"><div><h2 className="font-display text-4xl md:text-5xl text-white">Your operations account.</h2><p className="text-slate-500 mt-3 max-w-xl leading-7">A private control surface for the identity that manages Gaming Pub. Customer account data and admin actions remain separated by server-side role checks.</p></div><Button variant="outline" onClick={logout} className="border-white/15">Sign out</Button></div><div className="grid md:grid-cols-3 gap-4 mb-6"><div className="admin-status-card"><div className="eyebrow mb-3">SESSION</div><div className="flex items-center gap-2 text-white"><span className="signal-dot" /> Authenticated</div><p className="text-xs text-slate-600 mt-3">Managed session cookie active</p></div><div className="admin-status-card"><div className="eyebrow mb-3">ROLE</div><div className="profile-spectrum-text font-display text-xl">Administrator</div><p className="text-xs text-slate-600 mt-3">Server-side RBAC enforced</p></div><div className="admin-status-card"><div className="eyebrow mb-3">ACCESS</div><div className="text-white">Catalog · Orders · Inventory</div><p className="text-xs text-slate-600 mt-3">Operational permissions enabled</p></div></div><div className="grid lg:grid-cols-2 gap-5"><div className="glass-panel p-6"><div className="eyebrow mb-3">IDENTITY DETAILS</div><div className="space-y-4"><div className="admin-detail-row"><span>Display name</span><strong>{user.name || "Not configured"}</strong></div><div className="admin-detail-row"><span>Email</span><strong>{user.email || "Not exposed"}</strong></div><div className="admin-detail-row"><span>Login method</span><strong>{user.loginMethod || "Managed OAuth"}</strong></div><div className="admin-detail-row"><span>Last signed in</span><strong>{formatDate(user.lastSignedIn)}</strong></div></div></div><div className="glass-panel p-6"><div className="eyebrow mb-3">QUICK OPERATIONS</div><div className="grid grid-cols-2 gap-3"><Link href="/admin/products" className="admin-quick-link"><ShoppingBag className="w-5 h-5" /><span>Configure catalog</span><ArrowUpRight className="w-4 h-4" /></Link><Link href="/admin/orders" className="admin-quick-link"><Package className="w-5 h-5" /><span>Review orders</span><ArrowUpRight className="w-4 h-4" /></Link><Link href="/admin/inventory" className="admin-quick-link"><Truck className="w-5 h-5" /><span>Adjust inventory</span><ArrowUpRight className="w-4 h-4" /></Link><Link href="/admin/analytics" className="admin-quick-link"><Zap className="w-5 h-5" /><span>View analytics</span><ArrowUpRight className="w-4 h-4" /></Link></div></div></div><div className="glass-panel p-6 mt-5"><div className="flex items-start gap-4"><ShieldCheck className="w-6 h-6 text-cyan-300 shrink-0" /><div><div className="eyebrow mb-2">SECURITY POSTURE</div><p className="text-sm text-slate-400 leading-6">Admin procedures require the server-side administrator role. Prices, stock, order transitions, request transitions, and customer ownership are never trusted from this browser.</p></div></div></div></main></div></div></StoreShell>; }

export function AdminPage() { const adminItems: Array<[string, string, React.ElementType]> = [["overview", "Dashboard", LayoutDashboard], ["orders", "Orders", Package], ["products", "Products", ShoppingBag], ["requests", "Requests", ClipboardList], ["inventory", "Inventory", Truck], ["analytics", "Analytics", Zap], ["settings", "Settings", Settings], ["account", "Admin account", CircleUserRound]]; const { user, isAuthenticated } = useAuth(); const [location] = useLocation(); const tab = location.split("/")[2] ?? "overview"; if (!isAuthenticated) return <StoreShell><div className="max-w-[1440px] mx-auto px-5 py-24"><LoginPanel title="Admin access required" /></div></StoreShell>; if (!user || user.role === "user") return <StoreShell><div className="max-w-[900px] mx-auto px-5 py-24"><EmptyState title="Access denied" body="This route is protected by server-side role checks." action={<Link href="/"><Button variant="outline">Return to storefront</Button></Link>} /></div></StoreShell>; return <StoreShell><div className="max-w-[1440px] mx-auto px-5 lg:px-10 py-12"><div className="flex flex-col lg:flex-row gap-8"><aside className="lg:w-56 shrink-0"><div className="eyebrow mb-3">OPERATIONS CONSOLE</div><h1 className="font-display text-2xl text-white mb-7">Command center</h1><div className="space-y-1">{adminItems.map(([key, label, Icon]) => <Link key={String(key)} href={key === "overview" ? "/admin" : `/admin/${key}`} className={cn("account-nav", tab === key && "active")}><Icon className="w-4 h-4" />{label}</Link>)}</div></aside><div className="flex-1 min-w-0">{tab === "overview" && <AdminOverview />}{tab === "orders" && <AdminOrders />}{tab === "products" && <AdminProducts />}{tab === "requests" && <AdminRequests />}{tab === "inventory" && <AdminInventory />}{tab === "analytics" && <AdminAnalytics />}{tab === "settings" && <AdminSettings />}</div></div></div></StoreShell>; }
function AdminOverview() { const data = trpc.admin.overview.useQuery(); return <div><AdminTitle eyebrow="DASHBOARD" title="Store signal" body="Derived from live transactional data. Revenue includes completed orders only." />{data.isLoading ? <GridSkeleton /> : <><div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-4 mb-8"><Metric label="Total orders" value={String(data.data?.orderStats?.total ?? 0)} /><Metric label="Pending" value={String(data.data?.orderStats?.pending ?? 0)} /><Metric label="Completed" value={String(data.data?.orderStats?.completed ?? 0)} /><Metric label="Revenue" value={formatMoney(data.data?.revenue ?? 0)} /></div><div className="grid lg:grid-cols-2 gap-5"><div className="glass-panel p-6"><SectionHeading eyebrow="REQUEST CENTER" title="Demand, not revenue" /><div className="grid grid-cols-3 gap-3"><Metric label="All" value={String(data.data?.requestStats?.total ?? 0)} /><Metric label="Pending" value={String(data.data?.requestStats?.pending ?? 0)} /><Metric label="Completed" value={String(data.data?.requestStats?.completed ?? 0)} /></div></div><div className="glass-panel p-6"><SectionHeading eyebrow="CATALOG" title="Configured inventory" /><div className="grid grid-cols-2 gap-3"><Metric label="Products" value={String(data.data?.productStats?.total ?? 0)} /><Metric label="Customers" value={String(data.data?.customerStats?.total ?? 0)} /></div></div></div></>}</div>; }
function AdminTitle({ eyebrow, title, body }: { eyebrow: string; title: string; body: string }) { return <div className="mb-8"><div className="eyebrow mb-3">{eyebrow}</div><h2 className="font-display text-4xl text-white">{title}</h2><p className="text-slate-500 mt-3">{body}</p></div>; }
function AdminOrders() { const orders = trpc.admin.orders.useQuery(); const update = trpc.admin.orderStatus.useMutation({ onSuccess: () => { toast.success("Order status updated"); orders.refetch(); }, onError: (e) => toast.error(e.message) }); return <div><AdminTitle eyebrow="OPERATIONS / ORDERS" title="Order queue" body="Every status change is validated against the allowed lifecycle on the server." /><div className="glass-panel overflow-x-auto"><table className="data-table"><thead><tr><th>Order</th><th>Status</th><th>Total</th><th>Created</th><th>Next action</th></tr></thead><tbody>{orders.data?.map((order) => <tr key={order.id}><td className="text-white">#{order.id}</td><td><Badge className="badge-status">{ORDER_STATUS_LABELS[order.status]}</Badge></td><td className="text-cyan-300">{formatMoney(order.total)}</td><td>{formatDate(order.createdAt)}</td><td><StatusAction status={order.status} onChange={(status) => update.mutate({ orderId: order.id, status })} /></td></tr>)}</tbody></table>{!orders.data?.length && <EmptyState title="No orders yet" body="Orders will appear here once customers submit them." />}</div></div>; }
function StatusAction({ status, onChange }: { status: string; onChange: (status: "ACCEPTED" | "PREPARING" | "READY" | "COMPLETED" | "REJECTED" | "CANCELLED") => void }) { const next: Record<string, Array<[string, "ACCEPTED" | "PREPARING" | "READY" | "COMPLETED" | "REJECTED" | "CANCELLED"]>> = { PENDING_ACCEPTANCE: [["Accept", "ACCEPTED"], ["Reject", "REJECTED"]], ACCEPTED: [["Preparing", "PREPARING"]], PREPARING: [["Ready", "READY"]], READY: [["Complete", "COMPLETED"]], COMPLETED: [], REJECTED: [], CANCELLED: [] }; return <div className="flex gap-1 flex-wrap">{next[status]?.map(([label, value]) => <Button key={value} variant="outline" size="sm" className="h-8 border-white/10 text-xs" onClick={() => onChange(value)}>{label}</Button>)}</div>; }
function RichTextEditor({ value, onChange }: { value: string; onChange: (value: string) => void }) { const editor = useRef<HTMLDivElement>(null); useEffect(() => { if (editor.current && editor.current.innerHTML !== value) editor.current.innerHTML = value; }, [value]); const run = (command: string, argument?: string) => { editor.current?.focus(); document.execCommand(command, false, argument); onChange(editor.current?.innerHTML ?? ""); }; const addLink = () => { const url = window.prompt("Paste the link URL"); if (url) run("createLink", url); }; return <div className="rich-editor"><div className="rich-toolbar"><Button type="button" variant="ghost" size="icon" className="h-8 w-8" onMouseDown={(event) => event.preventDefault()} onClick={() => run("bold")} aria-label="Bold"><Bold className="w-4 h-4" /></Button><Button type="button" variant="ghost" size="icon" className="h-8 w-8" onMouseDown={(event) => event.preventDefault()} onClick={() => run("italic")} aria-label="Italic"><Italic className="w-4 h-4" /></Button><Button type="button" variant="ghost" size="icon" className="h-8 w-8" onMouseDown={(event) => event.preventDefault()} onClick={() => run("insertUnorderedList")} aria-label="Bullet list"><List className="w-4 h-4" /></Button><Button type="button" variant="ghost" size="icon" className="h-8 w-8" onMouseDown={(event) => event.preventDefault()} onClick={() => run("insertOrderedList")} aria-label="Numbered list"><ListOrdered className="w-4 h-4" /></Button><Button type="button" variant="ghost" size="icon" className="h-8 w-8" onMouseDown={(event) => event.preventDefault()} onClick={addLink} aria-label="Add link"><LinkIcon className="w-4 h-4" /></Button><span className="text-[10px] text-slate-600 ml-2">Format the customer-facing description</span></div><div ref={editor} contentEditable suppressContentEditableWarning onInput={() => onChange(editor.current?.innerHTML ?? "")} className="rich-editor-surface" role="textbox" aria-multiline="true" data-placeholder="Write a rich description…" /></div>; }

function AdminProducts() { const products = trpc.admin.products.useQuery(); const { user } = useAuth(); const canEdit = user?.role === "admin"; const [location] = useLocation(); const editFromUrl = new URLSearchParams(location.split("?")[1] ?? "").get("edit"); type EditorForm = { name: string; category: CategoryKey; price: string; stock: string; size: string; genre: string; platform: string; developer: string; publisher: string; releaseDate: string; description: string; availability: boolean; unlimitedInventory: boolean; featured: boolean; menuOrder: number; coverImage: string; gallery: string[]; backgroundImage: string; imdbRating: string; imdbId: string; imdbUrl: string; imdbTitle: string; imdbYear: string }; const blank: EditorForm = { name: "", category: "GAME", price: "", stock: "", size: "", genre: "", platform: "", developer: "", publisher: "", releaseDate: "", description: "", availability: false, unlimitedInventory: false, featured: false, menuOrder: 0, coverImage: "", gallery: [], backgroundImage: "", imdbRating: "", imdbId: "", imdbUrl: "", imdbTitle: "", imdbYear: "" }; const [editing, setEditing] = useState<Product | null>(null); const [form, setForm] = useState<EditorForm>(blank); const [csv, setCsv] = useState(""); const [importResult, setImportResult] = useState<{ imported: number; errors: string[] } | null>(null); const [draggingId, setDraggingId] = useState<number | null>(null); const patch = (key: keyof EditorForm, value: string | boolean | number | string[]) => setForm((current) => ({ ...current, [key]: value })); const galleryOf = (product: Product) => Array.isArray(product.gallery) ? product.gallery.filter((value): value is string => typeof value === "string") : []; const syncProduct = (product: Product) => { setEditing(product); setForm({ name: product.name, category: product.category, price: product.price ?? "", stock: String(product.stock ?? ""), size: product.size ?? "", genre: product.genre ?? "", platform: product.platform ?? "", developer: product.developer ?? "", publisher: product.publisher ?? "", releaseDate: product.releaseDate ?? "", description: product.description ?? "", availability: product.availability, unlimitedInventory: product.unlimitedInventory, featured: product.featured, menuOrder: product.menuOrder, coverImage: product.coverImage ?? "", gallery: galleryOf(product), backgroundImage: product.backgroundImage ?? "", imdbRating: product.imdbRating ?? "", imdbId: product.imdbId ?? "", imdbUrl: product.imdbUrl ?? "", imdbTitle: product.imdbTitle ?? "", imdbYear: product.imdbYear ?? "" }); }; const reset = () => { setEditing(null); setForm(blank); }; const save = trpc.admin.productUpsert.useMutation({ onSuccess: (product) => { toast.success("Product saved"); products.refetch(); if (editing && product) syncProduct(product); else reset(); }, onError: (e) => toast.error(e.message) }); const del = trpc.admin.productDelete.useMutation({ onSuccess: () => { toast.success("Product deleted"); products.refetch(); reset(); }, onError: (e) => toast.error(e.message) }); const csvImport = trpc.admin.productsImport.useMutation({ onSuccess: (result) => { setImportResult(result); products.refetch(); toast.success(`${result.imported} product rows imported`); }, onError: (e) => toast.error(e.message) }); const mediaUpload = trpc.admin.productMediaUpload.useMutation({ onSuccess: (product) => { if (product) syncProduct(product); products.refetch(); toast.success("Media uploaded"); }, onError: (e) => toast.error(e.message) }); const galleryRemove = trpc.admin.productGalleryRemove.useMutation({ onSuccess: (product) => { if (product) syncProduct(product); products.refetch(); toast.success("Gallery image removed"); }, onError: (e) => toast.error(e.message) }); const reorder = trpc.admin.gameMenuReorder.useMutation({ onSuccess: () => { products.refetch(); toast.success("Game menu order saved"); }, onError: (e) => toast.error(e.message) }); const exportCsv = () => { const headers = ["id", "name", "category", "price", "availability", "stock", "unlimitedInventory", "featured", "menuOrder", "size", "genre", "platform", "developer", "publisher", "releaseDate", "description", "coverImage", "gallery", "imdbRating", "imdbId", "imdbUrl", "imdbTitle", "imdbYear"]; const cell = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`; const rows = (products.data ?? []).map((product) => [product.id, product.name, product.category, product.price, product.availability, product.stock, product.unlimitedInventory, product.featured, product.menuOrder, product.size, product.genre, product.platform, product.developer, product.publisher, product.releaseDate, product.description, product.coverImage, galleryOf(product).join(" | "), product.featured, product.menuOrder, product.imdbRating, product.imdbId, product.imdbUrl, product.imdbTitle, product.imdbYear].map(cell).join(",")); const blob = new Blob([[headers.map(cell).join(","), ...rows].join("\n")], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `gaming-pub-catalog-${new Date().toISOString().slice(0, 10)}.csv`; anchor.click(); URL.revokeObjectURL(url); toast.success("Catalog CSV exported"); }; const edit = (product: Product) => { syncProduct(product); window.scrollTo({ top: 0, behavior: "smooth" }); }; useEffect(() => { if (!editing && editFromUrl && products.data) { const selected = products.data.find((product) => product.id === Number(editFromUrl)); if (selected) edit(selected); } }, [editFromUrl, editing, products.data]); const readDataUrl = (file: File) => new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result ?? "")); reader.onerror = () => reject(new Error("Unable to read image")); reader.readAsDataURL(file); }); const upload = async (kind: "cover" | "gallery", fileList: FileList | null) => { if (!editing || !fileList?.length) return; try { const files = await Promise.all(Array.from(fileList).map(async (file) => ({ kind, fileName: file.name, mimeType: file.type, data: await readDataUrl(file) }))); mediaUpload.mutate({ productId: editing.id, files }); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to read image"); } }; const gameProducts = useMemo(() => (products.data ?? []).filter((product) => product.category === "GAME").sort((a, b) => a.menuOrder - b.menuOrder || a.name.localeCompare(b.name)), [products.data]); const moveGame = (targetId: number) => { if (!canEdit || draggingId === null || draggingId === targetId) return; const next = [...gameProducts]; const from = next.findIndex((product) => product.id === draggingId); const to = next.findIndex((product) => product.id === targetId); if (from < 0 || to < 0) return; const [moved] = next.splice(from, 1); next.splice(to, 0, moved); reorder.mutate({ items: next.map((product, index) => ({ productId: product.id, menuOrder: index })) }); setDraggingId(null); }; return <div><div className="flex flex-wrap items-end justify-between gap-4 mb-8"><AdminTitle eyebrow="CATALOG / PRODUCTS" title="Configure listings" body="Administrators can add and fully edit games, movies, and series — including rich descriptions, ratings, artwork, and menu placement." /><Button variant="outline" className="border-white/15 mb-1" onClick={exportCsv} disabled={!products.data?.length || !canEdit}><Download className="w-4 h-4 mr-2" /> Export live CSV</Button></div>{!canEdit && <div className="glass-panel p-4 mb-6 text-sm text-amber-200/80">Only the administrator can create or edit movies and series, change artwork, and reorder the game menu.</div>}<div className="glass-panel p-5 mb-6"><div className="flex flex-wrap items-center justify-between gap-3 mb-5"><div><div className="eyebrow">{editing ? `EDITING #${editing.id}` : "ADD PRODUCT"}</div><p className="text-xs text-slate-500 mt-2">Rich descriptions support bold text, lists, and links. Upload a cover and gallery directly from this editor.</p></div>{editing && <Button variant="ghost" size="sm" onClick={reset}>Cancel edit</Button>}</div><div className="grid md:grid-cols-2 xl:grid-cols-4 gap-3"><Input disabled={!canEdit} value={form.name} onChange={(e) => patch("name", e.target.value)} placeholder="Custom title / heading" className="field-input xl:col-span-2" /><select disabled={!canEdit} value={form.category} onChange={(e) => patch("category", e.target.value as CategoryKey)} className="field-select"><option value="GAME">Game</option><option value="MOVIE">Movie</option><option value="TV_SHOW">Series</option><option value="HARDWARE">Hardware</option><option value="OTHER">Other</option></select><Input disabled={!canEdit} value={form.price} onChange={(e) => patch("price", e.target.value)} placeholder="Price (EGP)" type="number" min="0" className="field-input" /><Input disabled={!canEdit} value={form.stock} onChange={(e) => patch("stock", e.target.value)} placeholder="Stock quantity" type="number" min="0" className="field-input" /><Input disabled={!canEdit} value={form.size} onChange={(e) => patch("size", e.target.value)} placeholder="Game size (e.g. 85 GB)" className="field-input" /><Input disabled={!canEdit} value={form.genre} onChange={(e) => patch("genre", e.target.value)} placeholder="Genres" className="field-input" /><Input disabled={!canEdit} value={form.platform} onChange={(e) => patch("platform", e.target.value)} placeholder="Platform" className="field-input" /><Input disabled={!canEdit} value={form.developer} onChange={(e) => patch("developer", e.target.value)} placeholder="Developer" className="field-input" /><Input disabled={!canEdit} value={form.publisher} onChange={(e) => patch("publisher", e.target.value)} placeholder="Publisher" className="field-input" /><Input disabled={!canEdit} value={form.releaseDate} onChange={(e) => patch("releaseDate", e.target.value)} placeholder="Release date / year" className="field-input" /><Input disabled={!canEdit} value={form.imdbRating} onChange={(e) => patch("imdbRating", e.target.value)} placeholder="IMDb rating / 10" type="number" min="0" max="10" step="0.1" className="field-input" /><Input disabled={!canEdit} value={form.imdbTitle} onChange={(e) => patch("imdbTitle", e.target.value)} placeholder="IMDb verified title" className="field-input" /><Input disabled={!canEdit} value={form.imdbId} onChange={(e) => patch("imdbId", e.target.value)} placeholder="IMDb ID (tt1234567)" className="field-input" /><Input disabled={!canEdit} value={form.imdbUrl} onChange={(e) => patch("imdbUrl", e.target.value)} placeholder="IMDb URL" className="field-input" /><Input disabled={!canEdit} value={form.imdbYear} onChange={(e) => patch("imdbYear", e.target.value)} placeholder="IMDb year" className="field-input" /><Input disabled={!canEdit} value={form.backgroundImage} onChange={(e) => patch("backgroundImage", e.target.value)} placeholder="Heading background image URL" className="field-input xl:col-span-2" /><Input disabled={!canEdit} value={String(form.menuOrder)} onChange={(e) => patch("menuOrder", Number(e.target.value) || 0)} placeholder="Menu order" type="number" min="0" className="field-input" /><div className="md:col-span-2 xl:col-span-4"><div className="field-label mb-2">Rich description</div><RichTextEditor value={form.description} onChange={(value) => patch("description", value)} /></div></div><div className="flex flex-wrap items-center justify-between gap-4 mt-5"><div className="flex flex-wrap gap-5 text-sm text-slate-400"><label className="inline-flex items-center gap-2 cursor-pointer"><input disabled={!canEdit} type="checkbox" checked={form.availability} onChange={(e) => patch("availability", e.target.checked)} className="accent-cyan-300" /> Available in menu</label><label className="inline-flex items-center gap-2 cursor-pointer"><input disabled={!canEdit} type="checkbox" checked={form.unlimitedInventory} onChange={(e) => patch("unlimitedInventory", e.target.checked)} className="accent-cyan-300" /> Unlimited inventory</label><label className="inline-flex items-center gap-2 cursor-pointer text-pink-200"><input disabled={!canEdit} type="checkbox" checked={form.featured} onChange={(e) => patch("featured", e.target.checked)} className="accent-pink-300" /> Featured title</label></div><Button className="neon-button" disabled={!canEdit || !form.name.trim() || save.isPending} onClick={() => save.mutate({ id: editing?.id, name: form.name, category: form.category, price: form.price ? Number(form.price) : null, availability: form.availability, stock: form.stock ? Number(form.stock) : null, unlimitedInventory: form.unlimitedInventory, featured: form.featured, menuOrder: form.menuOrder, coverImage: form.coverImage || null, backgroundImage: form.backgroundImage || null, gallery: form.gallery, imdbRating: form.imdbRating ? Number(form.imdbRating) : null, imdbId: form.imdbId || undefined, imdbUrl: form.imdbUrl || undefined, imdbTitle: form.imdbTitle || undefined, imdbYear: form.imdbYear || undefined, size: form.size || undefined, genre: form.genre || undefined, platform: form.platform || undefined, developer: form.developer || undefined, publisher: form.publisher || undefined, releaseDate: form.releaseDate || undefined, description: form.description || undefined })}>{save.isPending ? "Saving…" : editing ? "Save full listing" : "Create product"}</Button></div></div>{editing && <div className="grid lg:grid-cols-2 gap-5 mb-6"><div className="glass-panel p-5"><div className="eyebrow mb-3">COVER ART</div><div className="media-cover-preview">{form.coverImage ? <img src={form.coverImage} alt="Current cover" /> : <div className="media-empty"><ImagePlus className="w-6 h-6" />No cover uploaded</div>}</div><label className="neon-button inline-flex items-center justify-center px-4 py-3 mt-4 cursor-pointer"><ImagePlus className="w-4 h-4 mr-2" /> Upload / replace cover<input disabled={!canEdit || mediaUpload.isPending} type="file" accept="image/jpeg,image/png,image/webp,image/avif" className="sr-only" onChange={(e) => upload("cover", e.target.files)} /></label></div><div className="glass-panel p-5"><div className="flex items-center justify-between gap-3 mb-3"><div className="eyebrow">GALLERY PHOTOS</div><label className="text-xs text-cyan-300 cursor-pointer hover:text-white"><ImagePlus className="w-3 h-3 inline mr-1" /> Add photos<input disabled={!canEdit || mediaUpload.isPending} type="file" multiple accept="image/jpeg,image/png,image/webp,image/avif" className="sr-only" onChange={(e) => upload("gallery", e.target.files)} /></label></div>{form.gallery.length ? <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">{form.gallery.map((url) => <div key={url} className="media-gallery-item"><img src={url} alt="Gallery" /><button disabled={!canEdit || galleryRemove.isPending} type="button" onClick={() => galleryRemove.mutate({ productId: editing.id, url })} className="media-remove" aria-label="Remove gallery image">×</button></div>)}</div> : <div className="media-empty min-h-28">No gallery photos yet</div>}</div></div>}<div className="glass-panel p-5 mb-6"><div className="flex flex-wrap items-center justify-between gap-3 mb-3"><div><div className="eyebrow">GAME MENU / ORDER</div><p className="text-sm text-slate-500 mt-2">Drag a game onto another game to reorder the customer menu. Featured titles appear first.</p></div>{reorder.isPending && <span className="text-xs text-cyan-300">Saving order…</span>}</div><div className="space-y-2">{gameProducts.map((product) => <div key={product.id} draggable={canEdit} onDragStart={() => setDraggingId(product.id)} onDragOver={(event) => event.preventDefault()} onDrop={() => moveGame(product.id)} className={cn("menu-order-row", draggingId === product.id && "dragging")}><GripVertical className="w-4 h-4 text-slate-600 shrink-0" /><img src={product.coverImage ?? HERO_ART} alt="" className="w-10 h-10 object-cover" /><span className="flex-1 text-sm text-white truncate">{product.name}</span>{product.featured && <span className="badge badge-on">Featured</span>}<span className="text-xs text-slate-600">#{product.menuOrder + 1}</span></div>)}</div></div><div className="glass-panel p-5 mb-6"><div className="flex flex-wrap items-center justify-between gap-3 mb-2"><div className="eyebrow">BULK IMPORT / CSV</div><Button variant="outline" size="sm" className="border-white/15" onClick={exportCsv} disabled={!products.data?.length || !canEdit}><Download className="w-3 h-3 mr-2" /> Download current catalog</Button></div><p className="text-sm text-slate-500 leading-6 mb-4">Export, edit, and re-import the same CSV. Movies and series can only be created or changed by the administrator.</p><Textarea rows={5} value={csv} onChange={(e) => setCsv(e.target.value)} placeholder="name,category,price,availability,stock,size,genre,platform,featured,menuOrder\nExample Game,GAME,250,true,10,85 GB,RPG,PC,true,0" className="field-input font-mono text-xs" /><div className="flex flex-wrap items-center gap-3 mt-4"><input disabled={!canEdit} type="file" accept=".csv,text/csv" className="text-xs text-slate-500 file:mr-3 file:border file:border-white/15 file:bg-white/5 file:px-3 file:py-2 file:text-xs file:text-slate-300" onChange={(e) => { const file = e.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => setCsv(String(reader.result ?? "")); reader.readAsText(file); }} /><Button className="neon-button" disabled={!canEdit || !csv.trim() || csvImport.isPending} onClick={() => csvImport.mutate({ csv })}>{csvImport.isPending ? "Importing…" : "Import CSV"}</Button></div>{importResult && <div className="mt-4 text-xs text-slate-400">Imported <span className="text-cyan-300">{importResult.imported}</span> rows{importResult.errors.length ? ` · ${importResult.errors.length} rejected` : ""}{importResult.errors.length > 0 && <div className="mt-2 text-amber-300/80 space-y-1">{importResult.errors.slice(0, 4).map((error) => <div key={error}>{error}</div>)}</div>}</div>}</div><div className="glass-panel overflow-x-auto"><table className="data-table"><thead><tr><th>Product</th><th>Category</th><th>Size</th><th>Price</th><th>Stock</th><th>Featured</th><th>Status</th><th /></tr></thead><tbody>{products.data?.map((product) => <tr key={product.id}><td className="text-white max-w-[260px] truncate">{product.name}</td><td>{CATEGORY_LABELS[product.category]}</td><td>{product.size || "—"}</td><td className="text-cyan-300">{formatMoney(product.price)}</td><td>{product.unlimitedInventory ? "∞" : product.stock ?? "—"}</td><td>{product.featured ? "Yes" : "—"}</td><td><span className={cn("badge", product.availability ? "badge-on" : "badge-off")}>{product.availability ? "Available" : "Hidden"}</span></td><td><div className="flex justify-end gap-2">{canEdit && <><Button variant="ghost" size="sm" onClick={() => edit(product)}>Edit</Button><Button variant="ghost" size="sm" className="text-red-300" onClick={() => { if (window.confirm("Delete this product? This cannot be undone.")) del.mutate({ productId: product.id }); }}>Delete</Button></>}</div></td></tr>)}</tbody></table></div></div>; }
function AdminRequests() { const requests = trpc.admin.requests.useQuery(); const update = trpc.admin.requestStatus.useMutation({ onSuccess: () => { toast.success("Request status updated"); requests.refetch(); }, onError: (e) => toast.error(e.message) }); return <div><AdminTitle eyebrow="DEMAND / REQUESTS" title="Request center" body="Requests remain isolated from purchases, stock, and revenue. Product creation requires a separate review step." /><div className="glass-panel overflow-x-auto"><table className="data-table"><thead><tr><th>Request</th><th>Type</th><th>Status</th><th>Submitted</th><th>Next action</th></tr></thead><tbody>{requests.data?.map((request) => <tr key={request.id}><td><div className="text-white">{request.title}</div><div className="text-xs text-slate-600 mt-1">{request.requestCode}</div></td><td>{request.type}</td><td><Badge className="badge-status">{REQUEST_STATUS_LABELS[request.status]}</Badge></td><td>{formatDate(request.createdAt)}</td><td><RequestStatusAction status={request.status} onChange={(status) => update.mutate({ requestId: request.id, status })} /></td></tr>)}</tbody></table>{!requests.data?.length && <EmptyState title="No requests yet" body="Customer demand will appear here independently from revenue." />}</div></div>; }
function RequestStatusAction({ status, onChange }: { status: string; onChange: (status: "REVIEWING" | "AVAILABLE" | "REJECTED" | "COMPLETED" | "CANCELLED") => void }) { const next: Record<string, Array<[string, "REVIEWING" | "AVAILABLE" | "REJECTED" | "COMPLETED" | "CANCELLED"]>> = { PENDING: [["Review", "REVIEWING"], ["Reject", "REJECTED"]], REVIEWING: [["Available", "AVAILABLE"], ["Reject", "REJECTED"]], AVAILABLE: [["Complete", "COMPLETED"]], COMPLETED: [], REJECTED: [], CANCELLED: [] }; return <div className="flex gap-1 flex-wrap">{next[status]?.map(([label, value]) => <Button key={value} variant="outline" size="sm" className="h-8 border-white/10 text-xs" onClick={() => onChange(value)}>{label}</Button>)}</div>; }
function AdminInventory() { const inventory = trpc.admin.inventory.useQuery(); const update = trpc.admin.inventoryUpdate.useMutation({ onSuccess: () => { toast.success("Inventory updated"); inventory.refetch(); }, onError: (e) => toast.error(e.message) }); return <div><AdminTitle eyebrow="OPERATIONS / INVENTORY" title="Stock control" body="Hardware stock is validated at order creation and reservations are released on terminal status changes." /><div className="glass-panel overflow-x-auto"><table className="data-table"><thead><tr><th>Product</th><th>Stock</th><th>Reserved</th><th>Available</th><th /></tr></thead><tbody>{inventory.data?.map(({ product, inventory: item }) => <tr key={item.id}><td className="text-white">{product.name}</td><td>{item.stock}</td><td>{item.reserved}</td><td className="text-cyan-300">{item.stock - item.reserved}</td><td><Button variant="outline" size="sm" onClick={() => { const next = window.prompt("New stock count", String(item.stock)); if (next !== null) update.mutate({ productId: product.id, stock: Number(next), reserved: item.reserved }); }}>Adjust</Button></td></tr>)}</tbody></table>{!inventory.data?.length && <EmptyState title="No inventory records" body="Create inventory-backed hardware entries to manage stock here." />}</div></div>; }
function AdminAnalytics() { const overview = trpc.admin.overview.useQuery(); return <div><AdminTitle eyebrow="INTELLIGENCE / ANALYTICS" title="What the data says" body="This surface derives metrics from orders and requests. No revenue or customer activity is hardcoded." /><div className="grid md:grid-cols-2 gap-5"><div className="glass-panel p-6"><div className="eyebrow mb-5">ORDER FUNNEL</div><div className="space-y-4"><Bar label="All orders" value={Number(overview.data?.orderStats?.total ?? 0)} max={Math.max(Number(overview.data?.orderStats?.total ?? 0), 1)} color="cyan" /><Bar label="Pending" value={Number(overview.data?.orderStats?.pending ?? 0)} max={Math.max(Number(overview.data?.orderStats?.total ?? 0), 1)} color="amber" /><Bar label="Completed" value={Number(overview.data?.orderStats?.completed ?? 0)} max={Math.max(Number(overview.data?.orderStats?.total ?? 0), 1)} color="violet" /></div></div><div className="glass-panel p-6"><div className="eyebrow mb-5">REQUEST FUNNEL</div><div className="space-y-4"><Bar label="All requests" value={Number(overview.data?.requestStats?.total ?? 0)} max={Math.max(Number(overview.data?.requestStats?.total ?? 0), 1)} color="cyan" /><Bar label="Pending" value={Number(overview.data?.requestStats?.pending ?? 0)} max={Math.max(Number(overview.data?.requestStats?.total ?? 0), 1)} color="amber" /><Bar label="Completed" value={Number(overview.data?.requestStats?.completed ?? 0)} max={Math.max(Number(overview.data?.requestStats?.total ?? 0), 1)} color="violet" /></div></div></div></div>; }
function Bar({ label, value, max, color }: { label: string; value: number; max: number; color: string }) { return <div><div className="flex justify-between text-sm mb-2"><span className="text-slate-400">{label}</span><span className="text-white">{value}</span></div><div className="h-2 bg-white/5"><div className={`h-full bg-${color}-300`} style={{ width: `${Math.min((value / max) * 100, 100)}%` }} /></div></div>; }
function AdminSettings() { const settings = trpc.admin.settings.useQuery(); const [whatsappBusinessNumber, setWhatsappBusinessNumber] = useState(""); const [englishTemplate, setEnglishTemplate] = useState(""); const [arabicTemplate, setArabicTemplate] = useState(""); const [loaded, setLoaded] = useState(false); useEffect(() => { if (settings.data && !loaded) { setWhatsappBusinessNumber(settings.data.whatsappBusinessNumber); setEnglishTemplate(settings.data.englishTemplate); setArabicTemplate(settings.data.arabicTemplate); setLoaded(true); } }, [settings.data, loaded]); const save = trpc.admin.settingsUpdate.useMutation({ onSuccess: (data) => { setWhatsappBusinessNumber(data.whatsappBusinessNumber); setEnglishTemplate(data.englishTemplate); setArabicTemplate(data.arabicTemplate); settings.refetch(); toast.success("WhatsApp settings saved"); }, onError: (e) => toast.error(e.message) }); return <div><AdminTitle eyebrow="SYSTEM / SETTINGS" title="Configuration surface" body="Configure customer communication and commercial data without editing deployment secrets." /><div className="glass-panel p-6 mb-5"><div className="eyebrow mb-2">ORDER COMMUNICATION</div><h3 className="font-display text-2xl text-white">WhatsApp business number</h3><p className="text-sm text-slate-500 leading-6 mt-3 max-w-2xl">This number receives order discussions. Customers are redirected with a pre-filled message after checkout.</p><div className="grid md:grid-cols-[1fr_auto] gap-3 mt-6"><Input value={whatsappBusinessNumber} onChange={(e) => setWhatsappBusinessNumber(e.target.value)} placeholder="2010 123 4567" className="field-input" inputMode="tel" aria-label="WhatsApp business number" /><Button className="neon-button" disabled={save.isPending || settings.isLoading} onClick={() => save.mutate({ whatsappBusinessNumber, englishTemplate, arabicTemplate })}>{save.isPending ? "Saving…" : "Save WhatsApp settings"}</Button></div><div className="grid lg:grid-cols-2 gap-5 mt-8"><div><label className="field-label">English order template</label><p className="text-xs text-slate-600 mb-2">Required placeholders: {"{{customerName}}"}, {"{{orderId}}"}, {"{{items}}"}, {"{{total}}"}, {"{{storage}}"}</p><Textarea rows={10} value={englishTemplate} onChange={(e) => setEnglishTemplate(e.target.value)} className="field-input font-mono text-xs" /></div><div dir="rtl"><label className="field-label">قالب الطلب باللغة العربية</label><p className="text-xs text-slate-600 mb-2">يجب الاحتفاظ بالمتغيرات: {"{{customerName}}"}، {"{{orderId}}"}، {"{{items}}"}، {"{{total}}"}، {"{{storage}}"}</p><Textarea rows={10} value={arabicTemplate} onChange={(e) => setArabicTemplate(e.target.value)} className="field-input font-mono text-xs" /></div></div><div className="flex items-center gap-2 text-xs mt-4"><span className={cn("signal-dot", whatsappBusinessNumber ? "" : "off")} />{whatsappBusinessNumber ? "Configured for order links" : "Not configured — order links need a business number"}</div></div><div className="grid md:grid-cols-2 gap-5"><InfoTile icon={<Settings />} title="Catalog configuration" body="Use Products to set real prices, availability, and stock. Unpriced listings remain unavailable to customers." /><InfoTile icon={<Users />} title="Roles" body="The owner identity is promoted to admin server-side. Customer records are scoped by authenticated user." /><InfoTile icon={<Package />} title="Supabase handoff" body="The current managed runtime provides the live database and auth in-session. External Supabase variables remain documented for a future connector-backed deployment." /><InfoTile icon={<ShieldIcon />} title="Safety rails" body="Prices, totals, availability, stock, and transitions are validated in the server procedures rather than accepted from the browser." /></div></div>; }
function ShieldIcon() { return <Check className="w-5 h-5" />; }
